from __future__ import annotations

from pathlib import Path

from question1.agent import SupportCopilot
from question2.agent import SupportPipeline

PUBLIC = ["T-1001", "T-1002", "T-1003", "T-1004"]


def breakdown(session):
    rows = []
    for call in session.calls:
        rows.append(
            f"| {call.label} | {call.input_tokens} | {call.cached_prefix_tokens} | "
            f"{call.output_tokens} | {call.points()} |"
        )
    return rows


def main():
    lines = [
        "# LLM cost report",
        "",
        "Generated by GitHub Actions using the repository's deterministic LLM simulator.",
        "Points = uncached input × 3 + cached input × 0.3 + output × 15.",
        "",
    ]
    for title, agent_type, ticket_ids in [
        ("Question 1 — single call", SupportCopilot, PUBLIC),
        ("Question 2 — four-stage pipeline", SupportPipeline, PUBLIC),
    ]:
        lines.extend([f"## {title}", ""])
        for ticket_id in ticket_ids:
            agent = agent_type()
            result = agent.handle_ticket(ticket_id)
            lines.extend([
                f"### {ticket_id}: {result.action} / {result.kb_article}",
                "",
                "| Call | Input tokens | Cached tokens | Output tokens | Points |",
                "|---|---:|---:|---:|---:|",
                *breakdown(agent.session),
                f"| **Total** | | | | **{agent.session.total_points()}** |",
                "",
            ])
    path = Path("COST_REPORT.md")
    path.write_text("\n".join(lines) + "\n")
    print(path.read_text())


if __name__ == "__main__":
    main()
